(()=>{'use strict';const encoded={"assets/ground-granite-v20.png":"","assets/rescue-terrain-v2.png":"","assets/rescue-girl-v2.png":""};const cache={};window.TanitTextures={get(path){if(!cache[path]){const raw=atob(encoded[path]),pixels=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)pixels[i]=raw.charCodeAt(i);const tex=new THREE.DataTexture(pixels,1024,1024,THREE.RGBAFormat,THREE.UnsignedByteType);tex.flipY=true;tex.magFilter=THREE.LinearFilter;tex.minFilter=THREE.LinearMipmapLinearFilter;tex.generateMipmaps=true;tex.needsUpdate=true;cache[path]=tex;}const copy=cache[path].clone();copy.needsUpdate=true;return copy;}};})();